//! The gateway's own relay key pair: generated by the kernel on first use,
//! stored privately in kernel state, never returned by any request.
use super::error::GatewayError;
use crate::config::DaemonConfig;
use crate::transport::relay_crypto;

#[derive(Clone)]
pub(super) struct GatewayIdentity {
    pub(super) private_key: String,
    pub(super) thumbprint: String,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct StoredIdentity {
    private_key: String,
}

impl GatewayIdentity {
    pub(super) fn load_or_create(config: &DaemonConfig) -> Result<Self, GatewayError> {
        let path = config
            .private_runtime_state_root()
            .join("gateway-identity.json");
        let stored = match std::fs::read(&path) {
            Ok(bytes) => serde_json::from_slice::<StoredIdentity>(&bytes)
                .map_err(|error| unavailable(format!("gateway identity is unreadable: {error}")))?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                let stored = StoredIdentity {
                    private_key: relay_crypto::generate_private_key_base64(),
                };
                let bytes = serde_json::to_vec(&stored).expect("identity serializes");
                crate::config::write_private_file(&path, &bytes).map_err(|error| {
                    unavailable(format!("cannot store gateway identity: {error}"))
                })?;
                stored
            }
            Err(error) => {
                return Err(unavailable(format!(
                    "cannot read gateway identity: {error}"
                )))
            }
        };
        let public_key = relay_crypto::public_key_from_private_key_base64(&stored.private_key)
            .map_err(|error| unavailable(error.to_string()))?;
        Ok(Self {
            thumbprint: crate::runtime::terminal_pairings::public_key_thumbprint(&public_key),
            private_key: stored.private_key,
        })
    }
}

fn unavailable(detail: String) -> GatewayError {
    GatewayError::Unreachable {
        name: "gateway".into(),
        detail,
    }
}
